"""C2 Ünite 3: Akademik yazı."""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lib import Unit, gap, listen, match, mc, order, speak, typ, variants, write  # noqa: E402

u = Unit("C2", 3, "Akademik yazı", "Academic Writing",
         "İsimleştirme ve karmaşık isim öbekleriyle yoğun akademik cümleler kurabilir, kaynakları doğru biçimde ve uygun bildirme fiilleriyle aktarabilir, intihalden kaçınarak özetleme ve yeniden ifade etme yapabilir ve birden fazla kaynağı sentezleyen kısa bir literatür değerlendirmesi yazabilirim.",
         ["isimleştirme ve sözcük yoğunluğu", "karmaşık isim öbekleri: the extent to which, a growing body of research", "kaynak gösterme ve bildirme fiilleri: argue, contend, acknowledge", "yeniden ifade etme, özetleme ve sentez", "kısa literatür değerlendirmesi"],
         ["üniversite", "bilim", "araştırma"],
         {"title": "Kaynaklar konuşuyor", "durationMinutes": 45,
          "goal": "Her gruba aynı konuda (örneğin ekran süresi ve uyku) üç kısa kurgusal araştırma özeti verilir. Gruplar kaynakları karşılaştırır, ortak ve çelişen bulguları belirler ve bunları uygun bildirme fiilleriyle (argue, find, suggest, acknowledge) bir paragrafta sentezler. Sonra her grup paragrafını sesli okur; sınıf, kaynakların sadece sıralanıp sıralanmadığını yoksa gerçekten karşılaştırılıp karşılaştırılmadığını değerlendirir."})

u.vocab([
    ("nominalisation", "isimleştirme", "Nominalisation is typical of academic writing.", "İsimleştirme akademik yazının tipik özelliğidir.", None),
    ("lexical density", "sözcük yoğunluğu", "Academic texts have high lexical density.", "Akademik metinlerin sözcük yoğunluğu yüksektir.", None),
    ("noun phrase", "isim öbeği", "Long noun phrases can be hard to read.", "Uzun isim öbeklerini okumak zor olabilir.", None),
    ("a body of research", "bir araştırmalar bütünü, literatür", "A growing body of research suggests ...", "Giderek büyüyen bir araştırmalar bütünü ... olduğunu gösteriyor.", None),
    ("the extent to which", "-in ne ölçüde ...", "We examined the extent to which diet affects mood.", "Beslenmenin ruh halini ne ölçüde etkilediğini inceledik.", None),
    ("citation", "kaynak gösterme, atıf", "Every claim needs a citation.", "Her iddia bir kaynak gerektirir.", None),
    ("reporting verb", "bildirme fiili", "\"Argue\" is a common reporting verb.", "\"Argue\" yaygın bir bildirme fiilidir.", None),
    ("contend", "ileri sürmek, savunmak", "Kaya (2019) contends that ...", "Kaya (2019) ... olduğunu ileri sürer.", None),
    ("assert", "iddia etmek (güçlü)", "The authors assert that the effect is universal.", "Yazarlar etkinin evrensel olduğunu iddia ediyor.", None),
    ("acknowledge", "kabul etmek", "The study acknowledges several limitations.", "Çalışma birkaç sınırlılığı kabul ediyor.", None),
    ("demonstrate", "kanıtlamak, açıkça göstermek", "The results demonstrate a clear link.", "Sonuçlar açık bir bağlantıyı kanıtlıyor.", None),
    ("refute", "çürütmek", "Later studies refuted this claim.", "Sonraki çalışmalar bu iddiayı çürüttü.", None),
    ("plagiarism", "intihal", "Plagiarism is a serious academic offence.", "İntihal ciddi bir akademik suçtur.", None),
    ("paraphrase", "kendi sözleriyle ifade etmek", "Paraphrase the main idea in your own words.", "Ana fikri kendi sözlerinizle ifade edin.", None),
    ("synthesise", "sentezlemek, birleştirmek", "A good review synthesises several sources.", "İyi bir değerlendirme birden fazla kaynağı sentezler.", None),
    ("findings", "bulgular", "The findings were published last year.", "Bulgular geçen yıl yayımlandı.", None),
    ("limitation", "sınırlılık", "One limitation of the study is its small sample.", "Çalışmanın bir sınırlılığı küçük örneklemidir.", None),
    ("sample", "örneklem", "The sample consisted of 200 students.", "Örneklem 200 öğrenciden oluşuyordu.", None),
    ("consistent with", "ile tutarlı", "These results are consistent with earlier studies.", "Bu sonuçlar önceki çalışmalarla tutarlı.", None),
    ("in line with", "ile uyumlu", "In line with Kaya (2019), we found ...", "Kaya (2019) ile uyumlu olarak ... bulduk.", None),
    ("a gap in the literature", "literatürde bir boşluk", "This study addresses a gap in the literature.", "Bu çalışma literatürdeki bir boşluğu ele alıyor.", None),
    ("et al.", "ve diğerleri (kaynakta)", "Morgan et al. (2021) found ...", "Morgan ve diğerleri (2021) ... buldu.", None),
    ("to date", "bugüne kadar", "To date, few studies have examined this.", "Bugüne kadar çok az çalışma bunu inceledi.", None),
])

# ---------------- Ders 1 ----------------
u.lesson(
    "İsimleştirme", "Fiil ve sıfatları isme çevirip cümleyi yeniden yapılandırarak (Prices rose sharply → a sharp rise in prices) yoğun ve nesnel akademik cümleler kurabilirim.",
    {"kind": "text", "title": "İki versiyon", "body": "Spoken version:\n\"Researchers looked at how much students slept and found that when students didn't sleep enough, they did worse in exams. Because of this, they think schools should teach students more about why sleep is important.\"\n\nAcademic version:\n\"An analysis of students' sleep patterns revealed a strong association between sleep deprivation and poor exam performance. These findings have led to calls for greater emphasis on sleep education in schools.\"",
     "questions": [
        mc("What did the researchers find?", ["Lack of sleep was linked to worse exam results.", "Students sleep too much.", "Exams cause sleep problems."], 0, "\"association between sleep deprivation and poor exam performance\""),
        mc("What do the findings suggest schools should do?", ["Start later", "Teach more about the importance of sleep", "Give fewer exams"], 1, "\"greater emphasis on sleep education\""),
     ]},
    {"explanation": "C1 Ünite 9'da isimleştirmeyi resmî dilin bir aracı olarak gördük. Akademik yazıda ise isimleştirme **merkezi** bir özelliktir.\n\n**Neden isimleştirme?**\n\n1. **Yoğunluk:** Daha az kelimeyle daha çok bilgi (*lexical density*)\n2. **Nesnellik:** Kişileri (*researchers, we, students*) arka plana atar\n3. **Bağlılık:** Bir önceki cümleyi isimle özetleyip devam ettirir (*These findings ...*)\n4. **Soyutlama:** Olayları kavramlara dönüştürür\n\n**Dönüşüm örnekleri:**\n\n| Konuşma dili (fiil / sıfat) | Akademik (isim) |\n|---|---|\n| Researchers **looked at** how much students **slept**. | **An analysis of** students' **sleep patterns** ... |\n| When students **didn't sleep enough**, they **did worse**. | ... an association between **sleep deprivation** and **poor performance**. |\n| Prices **rose sharply**. | There was **a sharp rise in prices**. |\n| The government **decided to** cut taxes. | **The government's decision to** cut taxes ... |\n| It is **important** to ... | **The importance of** ... |\n| People **can access** the internet more **easily**. | **Easier access to** the internet ... |\n\n**Dönüşüm adımları:**\n\n1. Fiil → isim: *rise → a rise*, *analyse → analysis*\n2. Zarf → sıfat: *sharply → sharp*, *easily → easier*\n3. Özne → iyelik ya da *of*: *the government decided → the government's decision*, *students slept → students' sleep*\n4. Yeni bir ana fiil ekleyin: *revealed, led to, resulted in, contributed to*\n\n**Dikkat:** Aşırı isimleştirme metni **anlaşılmaz** yapar. Amaç açıklık ve yoğunluk dengesidir.",
     "examples": [{"en": "The rapid growth of cities has contributed to an increase in air pollution.", "tr": "Şehirlerin hızlı büyümesi hava kirliliğindeki artışa katkıda bulunmuştur."},
                  {"en": "The introduction of the new policy resulted in a significant reduction in waste.", "tr": "Yeni politikanın uygulanması atıkta önemli bir azalmaya yol açtı."},
                  {"en": "Easier access to information has transformed education.", "tr": "Bilgiye daha kolay erişim eğitimi dönüştürdü."}],
     "turkishNote": "Türkçe akademik yazıda isimleştirme zaten çok yaygındır: \"-ma / -me\", \"-ış / -iş\" ekleriyle (\"artış\", \"azalma\", \"gelişme\"). Bu nedenle Türk öğrenciler İngilizce isimleştirmenin mantığını kolayca kavrar. Ancak sık yapılan bir hata, İngilizce isimden sonra gelen edatları karıştırmaktır: \"an increase in\" (✗ of), \"a decrease in\", \"access to\" (✗ for), \"the effect of X on Y\", \"a reduction in\". Bu edatları isimle birlikte ezberleyin."},
    [
        mc("İsimleştirilmiş hali: \"Prices rose sharply.\"", ["There was a sharp rise in prices.", "Prices had a rising sharply."], 0, "Nominalisation."),
        mc("Doğru edat: \"an increase ___ unemployment\"", ["in", "of"], 0, "an increase in."),
        mc("Doğru edat: \"access ___ education\"", ["to", "for"], 0, "access to."),
        mc("İsimleştirmenin bir avantajı:", ["Metni daha nesnel ve yoğun yapar.", "Metni daha samimi yapar."], 0, "Nesnellik ve yoğunluk."),
        gap("The government's ___ to raise taxes was unpopular. (DECIDE)", ["decision"], "decision."),
        gap("An ___ of the data revealed a clear pattern. (ANALYSE)", ["analysis"], "analysis."),
        gap("Sleep ___ can lead to poor concentration. (DEPRIVE)", ["deprivation"], "deprivation."),
        gap("The new law resulted in a significant ___ in road accidents. (REDUCE)", ["reduction", "decrease", "decline", "fall"], "reduction."),
        listen("The expansion of online learning during the past decade has had a profound effect on higher education. The availability of free courses has led to a dramatic increase in the number of adult learners.", "Ücretsiz kursların erişilebilirliği neye yol açtı?", ["Yetişkin öğrenci sayısında büyük bir artışa", "Üniversitelerin kapanmasına", "Ders ücretlerinin artmasına"], 0, "\"a dramatic increase in the number of adult learners\""),
        typ("İsimleştirin: \"Unemployment fell slightly last year.\" (There was a ...)", variants("There was a slight fall in unemployment last year.", "There was a slight decrease in unemployment last year.", "There was a slight decline in unemployment last year.", "There was a slight drop in unemployment last year.", "Last year, there was a slight fall in unemployment."), "There was a slight fall in unemployment last year."),
    ],
    {"kind": "speaking", "task": speak("Aşağıdaki günlük dilde yazılmış bilgileri, bir akademik sunumda söyleyeceğiniz gibi isimleştirme kullanarak yeniden ifade edin: (1) More and more people are using electric cars, so cities are building more charging stations. (2) When the city made buses free, many more people started using them. (3) Because young people can easily get information online, they read fewer newspapers. (4) The company changed its policy, and its customers became much more satisfied.",
                                       "One: The growing popularity of electric cars has led to the construction of more charging stations in cities. Two: The introduction of free buses resulted in a significant increase in passenger numbers. Three: Easier access to online information has contributed to a decline in newspaper readership among young people. Four: The change in the company's policy led to a considerable improvement in customer satisfaction.",
                                       ["İsimleştirme", "Doğru edatlar", "Yeni ana fiiller (led to, resulted in)", "Akademik ton"])},
)

# ---------------- Ders 2 ----------------
u.lesson(
    "Karmaşık isim öbekleri", "Ön ve arka niteleyicilerle karmaşık isim öbekleri (a rapidly growing body of research on ..., the extent to which ...) kurabilir ve okurken çözümleyebilirim.",
    {"kind": "text", "title": "Bir makale özeti (kurgusal)", "body": "A rapidly growing body of research on remote work has examined its effects on productivity and well-being. However, relatively little attention has been paid to the extent to which working from home affects young employees' long-term career development. This study, based on interviews with 120 recent graduates in three European countries, explores the challenges faced by those who began their careers during periods of mandatory remote work. The findings point to a significant lack of informal learning opportunities, particularly in the first year of employment.",
     "questions": [
        mc("Which group does the study focus on?", ["Senior managers", "Recent graduates", "Retired workers"], 1, "\"120 recent graduates\""),
        mc("What is the main finding?", ["Remote work increases salaries.", "There is a lack of informal learning opportunities.", "Graduates prefer the office."], 1, "\"a significant lack of informal learning opportunities\""),
     ]},
    {"explanation": "Akademik metinlerde bilgi büyük ölçüde **isim öbeklerinde** yoğunlaşır. Bir isim öbeği şöyle yapılanır:\n\n**(belirleyici) + (ön niteleyiciler) + BAŞ İSİM + (arka niteleyiciler)**\n\n| Belirleyici | Ön niteleyici | Baş isim | Arka niteleyici |\n|---|---|---|---|\n| a | rapidly growing | **body** | of research on remote work |\n| the | — | **challenges** | faced by those who began their careers ... |\n| a | significant | **lack** | of informal learning opportunities |\n| — | young employees' long-term career | **development** | — |\n\n**Ön niteleyiciler:**\n\n- Sıfat / zarf + sıfat: *a **rapidly growing** body*\n- İsim + isim: ***career** development*, ***climate change** policy*\n- İyelik: ***young employees'** development*\n\n**Arka niteleyiciler:**\n\n- Edat öbeği: *the effect **of noise on concentration***\n- İndirgenmiş sıfat cümlesi (C1 Ünite 4): *the challenges **faced by graduates***\n- Sıfat cümlesi: *those **who began their careers ...***\n- Mastar: *the decision **to close the factory***\n\n**Akademik yazının kalıp isim öbekleri:**\n\n| Kalıp | Örnek |\n|---|---|\n| **the extent to which** | *the extent to which diet affects mood* |\n| **the degree to which** | *the degree to which students participate* |\n| **the way(s) in which** | *the ways in which teachers give feedback* |\n| **the role of X in Y** | *the role of parents in early education* |\n| **the relationship between X and Y** | *the relationship between income and health* |\n| **the impact / effect of X on Y** | *the impact of social media on sleep* |\n\n**Okuma stratejisi:** Uzun bir isim öbeğinde önce **baş ismi** bulun, sonra ona eklenen bilgileri çözün.",
     "examples": [{"en": "This paper examines the extent to which social media use predicts loneliness.", "tr": "Bu makale sosyal medya kullanımının yalnızlığı ne ölçüde öngördüğünü inceliyor."},
                  {"en": "The relationship between income and health has been widely studied.", "tr": "Gelir ve sağlık arasındaki ilişki geniş çapta incelenmiştir."},
                  {"en": "the ways in which teachers give feedback to students", "tr": "öğretmenlerin öğrencilere geri bildirim verme biçimleri"}],
     "turkishNote": "Türkçede niteleyiciler her zaman ismin önüne gelir: \"uzaktan çalışmanın genç çalışanların uzun vadeli kariyer gelişimi üzerindeki etkisi\". İngilizcede ise niteleyiciler hem önde hem arkada olabilir: \"the effect of remote work on young employees' long-term career development\". Bu nedenle Türk öğrenciler İngilizce isim öbeklerini okurken baş ismi bulmakta zorlanır. Strateji: \"of\", \"on\", \"in\", \"by\", \"which\", \"who\" gibi kelimelerden önceki ismi bulun; genellikle baş isim odur."},
    [
        mc("\"a rapidly growing body of research on remote work\" baş isim:", ["research", "body"], 1, "Baş isim: body."),
        mc("\"the challenges faced by young graduates\" baş isim:", ["challenges", "graduates"], 0, "Baş isim: challenges."),
        mc("Doğru kalıp:", ["the extent which", "the extent to which"], 1, "the extent to which."),
        mc("Doğru edat: \"the impact of social media ___ sleep\"", ["on", "to"], 0, "the impact of X on Y."),
        gap("This study examines the ___ to which exercise improves mood. (ölçü)", ["extent", "degree"], "the extent to which."),
        gap("The relationship ___ diet and health is complex.", ["between"], "relationship between."),
        gap("We investigated the ways ___ which students use mobile apps.", ["in"], "the ways in which."),
        gap("Little attention has been ___ to this issue. (gösterilmek)", ["paid", "given"], "attention has been paid."),
        listen("The present study investigates the role of grandparents in the language development of bilingual children living in urban areas. Particular attention is paid to the degree to which regular contact with grandparents helps children maintain their heritage language.", "Çalışma neyi inceliyor?", ["Büyükanne ve büyükbabaların iki dilli çocukların dil gelişimindeki rolünü", "Şehirlerdeki okulların kalitesini", "Çocukların okul başarısını"], 0, "\"the role of grandparents in the language development of bilingual children\""),
        order(["the", "impact", "of", "social", "media", "on", "teenagers'", "sleep"], "the impact of social media on teenagers' sleep", "the impact of X on Y.", "sosyal medyanın gençlerin uykusu üzerindeki etkisi"),
    ],
    {"kind": "speaking", "task": speak("Kendi ilgi alanınızda yapılabilecek bir araştırma projesini, bir akademik konferansta 45 saniyelik bir giriş konuşmasıyla tanıtın. Projenin konusunu karmaşık isim öbekleri ve en az iki akademik kalıpla (the extent to which, the role of X in Y, the relationship between X and Y, the impact of X on Y, the ways in which) anlatın.",
                                       "Good afternoon. My proposed study focuses on the relationship between smartphone use and reading habits among university students in Turkey. Although a growing body of research has examined the impact of digital devices on attention, relatively little is known about the extent to which they have changed the ways in which young people read longer texts. Using a survey of around three hundred students and a series of follow-up interviews, the study will explore the role of reading apps in either encouraging or discouraging the reading of full-length books.",
                                       ["Karmaşık isim öbekleri", "Akademik kalıplar", "Doğru edatlar", "Akademik sunum tonu"])},
)

# ---------------- Ders 3 ----------------
u.lesson(
    "Kaynak gösterme ve bildirme fiilleri", "Kaynakları bütünleşik (Kaya (2019) argues ...) ve parantez içi ((Kaya, 2019)) biçimde aktarabilir ve tutumumu yansıtan uygun bildirme fiilini (argue, claim, demonstrate, acknowledge) seçebilirim.",
    {"kind": "text", "title": "Bir literatür değerlendirmesinden (kurgusal kaynaklar)", "body": "The effect of background music on concentration remains a matter of debate. Kaya (2019) argues that instrumental music can improve focus during repetitive tasks. Similarly, Morgan et al. (2021) found that students who listened to classical music while revising performed slightly better in memory tests. However, Chen (2020) contends that these benefits disappear when tasks become more complex. Indeed, several studies have demonstrated that music with lyrics significantly reduces reading comprehension (Patel, 2018; Ruiz and Okafor, 2022). Morgan et al. (2021) themselves acknowledge that their sample was small and limited to one university.",
     "questions": [
        mc("What does Chen (2020) argue?", ["Music always helps concentration.", "The benefits disappear with more complex tasks.", "Students should never listen to music."], 1, "\"these benefits disappear when tasks become more complex\""),
        mc("What limitation do Morgan et al. acknowledge?", ["Their sample was small.", "They used the wrong music.", "The tests were too easy."], 0, "\"their sample was small and limited to one university\""),
     ]},
    {"explanation": "**1. İki tür kaynak gösterme:**\n\n| Tür | Örnek | Vurgu |\n|---|---|---|\n| **Bütünleşik (integral)** | ***Kaya (2019)** argues that ...* | yazar |\n| **Parantez içi (non-integral)** | *Music can improve focus **(Kaya, 2019)**.* | bulgu |\n\n**Birden fazla kaynak:** *(Patel, 2018; Ruiz and Okafor, 2022)*\n**Üç ve daha fazla yazar:** *Morgan **et al.** (2021)*\n\n**2. Bildirme fiilleri ve tutum:** Fiil seçimi, kaynağa karşı **sizin tutumunuzu** gösterir!\n\n| Tutum | Fiiller | Örnek |\n|---|---|---|\n| **Nötr** | state, note, report, describe, find, observe | *Kaya (2019) **notes** that ...* |\n| **Görüş / iddia** | argue, claim, contend, maintain, assert, suggest | *Chen (2020) **contends** that ...* |\n| **Güçlü kanıt (yazar katılıyor)** | demonstrate, show, establish, confirm, prove | *Several studies have **demonstrated** that ...* |\n| **Şüphe (yazar katılmıyor)** | claim, allege, assume | *Some **claim** that ...* (dikkat: şüphe ima edebilir) |\n| **Kabul** | acknowledge, concede, admit | *They **acknowledge** that their sample was small.* |\n| **Karşı çıkma** | dispute, challenge, question, reject, refute | *Later studies **challenged** this view.* |\n\n**Dikkat:**\n\n- ***claim*** genellikle **şüphe** ima eder: *He claims to have invented it* (ama inanmıyorum).\n- ***demonstrate / prove*** güçlü fiillerdir; sadece **sağlam kanıt** için kullanın.\n- ***suggest*** temkinli bir fiildir (C1 Ünite 6).\n\n**3. Zaman kullanımı:**\n\n- **Geniş zaman:** Yazarın görüşü hâlâ geçerli: *Kaya (2019) **argues** that ...*\n- **Geçmiş zaman:** Belirli bir çalışmanın bulgusu: *Morgan et al. (2021) **found** that ...*\n- **Present perfect:** Genel araştırma alanı: *Several studies **have shown** that ...*",
     "examples": [{"en": "Kaya (2019) argues that music can improve focus.", "tr": "Kaya (2019) müziğin odaklanmayı artırabileceğini savunuyor."},
                  {"en": "Music can improve focus during simple tasks (Kaya, 2019).", "tr": "Müzik basit görevlerde odaklanmayı artırabilir (Kaya, 2019)."},
                  {"en": "Later studies have challenged this view (Chen, 2020; Patel, 2018).", "tr": "Sonraki çalışmalar bu görüşe itiraz etmiştir (Chen, 2020; Patel, 2018)."}],
     "turkishNote": "Türkçe akademik yazıda genellikle \"belirtmektedir\", \"ifade etmektedir\" ya da \"ileri sürmektedir\" gibi sınırlı sayıda fiil kullanılır. İngilizcede ise bildirme fiili seçimi yazarın tutumunu gösterir ve hakemler bunu dikkatle okur. Örneğin bir kaynağı \"Kaya claims that...\" diye aktarmak, ona şüpheyle baktığınızı ima eder. Ayrıca Türk öğrenciler \"says\" fiilini aşırı kullanır; akademik yazıda \"says\" yerine \"states\", \"notes\" ya da \"argues\" tercih edilir."},
    [
        mc("Parantez içi kaynak gösterme:", ["Kaya (2019) argues that ...", "... can improve focus (Kaya, 2019)."], 1, "Non-integral."),
        mc("Güçlü kanıt için:", ["demonstrate", "suggest"], 0, "demonstrate."),
        mc("Şüphe ima edebilecek fiil:", ["claim", "establish"], 0, "claim."),
        mc("Bir çalışmanın kendi zayıflığını kabul etmesi:", ["The authors acknowledge that ...", "The authors refute that ..."], 0, "acknowledge."),
        gap("Morgan ___ al. (2021) found a small positive effect.", ["et"], "et al."),
        gap("Several studies have ___ that sleep improves memory. (kanıtlamak)", ["demonstrated", "shown", "established", "confirmed"], "demonstrated."),
        gap("Chen (2020) ___ that the effect is only temporary. (ileri sürmek)", ["contends", "argues", "maintains", "claims", "suggests"], "contends."),
        gap("Later research ___ this view, showing that the results could not be repeated. (itiraz etmek)", ["challenged", "questioned", "disputed", "refuted"], "challenged."),
        listen("While Ahmed and Lewis argue that homework improves academic achievement at all ages, a large-scale review by Novak found no significant effect for primary school children. Ahmed and Lewis themselves concede that most of their data came from secondary schools.", "Ahmed ve Lewis neyi kabul ediyor?", ["Ödevin işe yaramadığını", "Verilerinin çoğunun ortaokul ve liselerden geldiğini", "Novak'ın haklı olduğunu"], 1, "\"most of their data came from secondary schools\""),
        match([("demonstrate", "güçlü kanıt"), ("argue", "görüş / iddia"), ("acknowledge", "kabul etmek"), ("challenge", "itiraz etmek"), ("note", "nötr aktarma")], "Her bildirme fiilini işleviyle eşleştirin."),
    ],
    {"kind": "speaking", "task": speak("Aşağıdaki üç kurgusal kaynağın bulgularını, bir seminerde sözlü olarak karşılaştırın (1 dakika). Her kaynak için uygun bir bildirme fiili seçin ve en az bir kez kabul, bir kez de itiraz fiili kullanın. Kaynak 1: Demir (2020): Günde 30 dakika yürüyüş stres seviyesini düşürüyor (200 kişilik bir çalışma). Kaynak 2: Walsh (2022): Etki sadece doğada yapılan yürüyüşlerde görülüyor; şehirde fark yok. Kaynak 3: Sato et al. (2023): Etki çok küçük ve katılımcıların kendi beyanına dayanıyor.",
                                       "Research on walking and stress has produced mixed results. Demir, in a 2020 study of two hundred adults, found that walking for thirty minutes a day significantly reduced stress levels. However, Walsh, writing in 2022, argues that this benefit only appears when people walk in natural settings, and reports no difference for walks in urban areas. More recently, Sato and colleagues have questioned the size of the effect altogether. They note that the improvement was very small, and they acknowledge that their data relied on participants' own reports, which may not be fully reliable. Taken together, these studies suggest that the link between walking and stress is real but more complex than early research implied.",
                                       ["Uygun bildirme fiilleri", "Kabul ve itiraz", "Doğru zaman kullanımı", "Karşılaştırmalı sentez"])},
)

# ---------------- Ders 4 ----------------
u.lesson(
    "Yeniden ifade, özet ve sentez", "Bir kaynağı intihalden kaçınarak kendi sözlerimle yeniden ifade edebilir (paraphrase), kısaca özetleyebilir ve birden fazla kaynağı karşılaştırarak sentezleyebilirim.",
    {"kind": "text", "title": "Orijinal ve iki yeniden ifade", "body": "Original (Lindqvist, 2021, fictional):\n\"Children who grow up in households where several languages are spoken often develop stronger problem-solving skills, possibly because they are constantly required to switch between different linguistic systems.\"\n\nParaphrase 1 (too close):\n\"Children who grow up in homes where many languages are spoken often develop better problem-solving skills, maybe because they always have to switch between different language systems (Lindqvist, 2021).\"\n\nParaphrase 2 (good):\n\"According to Lindqvist (2021), regular exposure to more than one language at home may enhance children's ability to solve problems, as moving between languages appears to train mental flexibility.\"",
     "questions": [
        mc("Why is Paraphrase 1 a problem?", ["It changes the meaning.", "It is too similar to the original.", "It has no citation."], 1, "Sadece birkaç kelime değiştirilmiş."),
        mc("What does Paraphrase 2 do well?", ["It copies the original exactly.", "It changes structure and vocabulary but keeps the meaning.", "It adds new information."], 1, "Yapı ve kelimeler değişmiş, anlam korunmuş."),
     ]},
    {"explanation": "**1. İntihal (plagiarism):** Başkasının fikrini ya da kelimelerini **kaynak göstermeden** kullanmak. Kaynak gösterseniz bile, metni **neredeyse aynen** kopyalayıp birkaç kelimeyi değiştirmek de intihal sayılabilir (*patchwriting*).\n\n**2. İyi bir yeniden ifade (paraphrase) için 5 teknik:**\n\n| Teknik | Orijinal | Yeniden ifade |\n|---|---|---|\n| **Eşanlamlı** | *stronger problem-solving skills* | *enhanced ability to solve problems* |\n| **Kelime türü değişimi** | *grow up in households where ...* | *exposure to ... at home* |\n| **Cümle yapısı değişimi** | *Children who ... develop ...* | *Exposure to ... may enhance children's ...* |\n| **Etken ↔ edilgen** | *They are required to switch* | *Switching ... is required* |\n| **Temkin korunur** | *possibly because* | *appears to* |\n\n**Teknik terimler** (*bilingual, problem-solving*) genellikle değiştirilmez.\n\n**3. Özet (summary):** Sadece **ana fikri** çok daha kısa bir şekilde verir; örnekler ve ayrıntılar atılır.\n\n*Lindqvist (2021) suggests that multilingual upbringing may improve problem-solving.*\n\n**4. Doğrudan alıntı (quotation):** Sadece kelimeler çok özel ya da güçlü olduğunda, kısa ve tırnak içinde:\n\n*Lindqvist (2021, p. 45) describes language switching as \"a daily workout for the brain\".*\n\n**5. Sentez (synthesis):** Kaynakları **sıralamak** değil, **ilişkilendirmek**:\n\n| Kötü (sıralama) | İyi (sentez) |\n|---|---|\n| *Kaya says X. Chen says Y. Patel says Z.* | *While Kaya (2019) and Patel (2018) both found X, Chen (2020) argues that this only applies when ...* |\n\n**Sentez kalıpları:** *Similarly, ... / In line with ... / In contrast, ... / While X ..., Y ... / Both X and Y ... / This is consistent with ... / X's findings support / contradict those of Y.*",
     "examples": [{"en": "Similarly, Morgan et al. (2021) found that ...", "tr": "Benzer şekilde, Morgan ve diğerleri (2021) ... olduğunu buldu."},
                  {"en": "This is consistent with earlier findings (Kaya, 2019).", "tr": "Bu önceki bulgularla tutarlıdır (Kaya, 2019)."},
                  {"en": "In contrast, Chen (2020) found no significant effect.", "tr": "Buna karşılık Chen (2020) anlamlı bir etki bulamadı."}],
     "turkishNote": "İntihal konusunda kurallar uluslararası üniversitelerde çok katıdır ve Türk öğrencilerin yurt dışında en sık karşılaştığı sorunlardan biri \"patchwriting\"dir: orijinal metni alıp sadece birkaç kelimeyi değiştirmek. Kaynak gösterilse bile bu durum intihal olarak değerlendirilebilir. Güvenli bir yöntem: Orijinali okuyun, kapatın, ana fikri Türkçe olarak düşünün, sonra İngilizce olarak sıfırdan yazın ve en son orijinalle karşılaştırın."},
    [
        mc("\"Patchwriting\" nedir?", ["Orijinalden birkaç kelime değiştirip neredeyse aynen kopyalamak", "Kaynakları bir listede göstermek"], 0, "Patchwriting."),
        mc("İyi bir sentez cümlesi:", ["Kaya says X. Chen says Y.", "While Kaya (2019) found X, Chen (2020) argues that ..."], 1, "Sentez."),
        mc("Özet (summary) nedir?", ["Bütün ayrıntıların tekrarı", "Ana fikrin çok daha kısa ifadesi"], 1, "Summary."),
        mc("Doğrudan alıntı ne zaman uygundur?", ["Her cümlede", "Kelimeler çok özel ya da güçlü olduğunda"], 1, "Quotation."),
        gap("___, Morgan et al. (2021) found a similar effect. (Benzer şekilde)", ["Similarly", "Likewise"], "Similarly."),
        gap("These results are ___ with earlier studies. (tutarlı)", ["consistent"], "consistent with."),
        gap("In ___, Chen (2020) found no effect. (Buna karşılık)", ["contrast"], "In contrast."),
        gap("___ to Lindqvist (2021), bilingual children may solve problems more easily. (-e göre)", ["According"], "According to."),
        listen("Both Novak and Ahmed found that short breaks improve concentration. However, while Novak recommends a five-minute break every half hour, Ahmed's data suggest that longer breaks every ninety minutes are more effective. Neither study, it should be noted, included participants over the age of forty.", "İki çalışmanın ortak sınırlılığı nedir?", ["İkisi de çok küçük", "İkisinde de 40 yaş üstü katılımcı yok", "İkisi de aynı sonucu buldu"], 1, "\"Neither study ... included participants over the age of forty\""),
        typ("Yeniden ifade edin (kendi sözlerinizle, isimleştirme ile): \"People who exercise regularly tend to sleep better.\" (Regular exercise ...)", variants("Regular exercise tends to improve sleep.", "Regular exercise tends to lead to better sleep.", "Regular exercise is associated with better sleep.", "Regular exercise tends to result in better sleep.", "Regular exercise appears to improve sleep quality.", "Regular exercise tends to improve sleep quality."), "Regular exercise tends to improve sleep."),
    ],
    {"kind": "speaking", "task": speak("Aşağıdaki kurgusal orijinal cümleyi önce kendi sözlerinizle yeniden ifade edin (paraphrase), sonra tek bir cümleyle özetleyin, sonra da başka bir kaynakla sentezleyin. Orijinal (Ortega, 2020): \"Employees who are given more control over their working hours report higher levels of job satisfaction and are less likely to leave their organisation within two years.\" Diğer kaynak (Brooks, 2022): Esnek çalışma saatleri iş tatminini artırıyor ama yöneticilerin iş yükünü de artırıyor.",
                                       "Paraphrase: According to Ortega (2020), allowing staff greater flexibility in when they work appears to increase their satisfaction and reduce the likelihood that they will resign in the short term. Summary: Ortega (2020) links flexible working hours to higher job satisfaction and lower staff turnover. Synthesis: Both Ortega (2020) and Brooks (2022) found that flexible working hours are associated with greater job satisfaction. However, Brooks also notes a potential drawback, namely an increase in managers' workload, which suggests that the benefits for employees may come at a cost for the organisation.",
                                       ["Gerçek yeniden ifade (yapı ve kelime değişimi)", "Kısa özet", "Sentez kalıpları", "Doğru kaynak gösterme"])},
)

# ---------------- Ders 5 ----------------
u.lesson(
    "Kısa literatür değerlendirmesi", "Birden fazla kaynağı tema etrafında sentezleyen, eleştirel değerlendirme yapan ve literatürdeki boşluğu belirten akademik bir paragraf / kısa literatür değerlendirmesi yazabilirim.",
    {"kind": "text", "title": "Örnek literatür değerlendirmesi (kurgusal kaynaklar)", "body": "The relationship between screen time and children's sleep has received considerable attention in recent years. A number of studies have found that the use of electronic devices before bedtime is associated with shorter sleep duration (Novak, 2019; Kaya and Ahmed, 2021). Kaya and Ahmed (2021), for instance, report that children who used tablets in the hour before bed slept, on average, thirty minutes less than those who did not. These findings are consistent with research suggesting that blue light may delay the release of melatonin (Ruiz, 2020).\n\nHowever, the evidence is not entirely consistent. Chen (2022) argues that the content of screen use, rather than the screen itself, is the key factor, noting that calming activities had little effect on sleep. Moreover, most existing studies rely on parents' reports, which may not be fully accurate, as Novak (2019) acknowledges.\n\nTo date, relatively few studies have used objective measures such as sleep-tracking devices, and almost none have focused on children under the age of five. The present study aims to address this gap.",
     "questions": [
        mc("What does Chen (2022) argue?", ["Screens always harm sleep.", "The type of content matters more than the screen itself.", "Children should not use screens."], 1, "\"the content of screen use, rather than the screen itself, is the key factor\""),
        mc("What gap does the review identify?", ["No studies on teenagers", "Few studies with objective measures and almost none on under-fives", "No studies on blue light"], 1, "\"few studies have used objective measures ... almost none have focused on children under the age of five\""),
     ]},
    {"explanation": "**Literatür değerlendirmesi (literature review),** bir konudaki mevcut araştırmaları **özetlemek** değil, onları **tematik olarak sentezleyip değerlendirmektir**.\n\n**Yapı:**\n\n| Bölüm | İşlev | Kalıplar |\n|---|---|---|\n| **1. Konuyu tanıtma** | Alanın önemini belirtme | *X has received considerable attention in recent years.* |\n| **2. Ortak bulgular** | Kaynakları gruplayıp sentezleme | *A number of studies have found that ... (A, 2019; B, 2021).* |\n| **3. Ayrıntı / örnek** | Bir çalışmayı öne çıkarma | *A and B (2021), for instance, report that ...* |\n| **4. Çelişkiler** | Farklı görüşleri karşılaştırma | *However, the evidence is not entirely consistent. C (2022) argues that ...* |\n| **5. Eleştirel değerlendirme** | Yöntem sınırlılıklarını belirtme | *Most existing studies rely on ..., which may ...* |\n| **6. Boşluk (gap)** | Henüz araştırılmamış alanı belirtme | *To date, relatively few studies have ... / Little is known about ...* |\n| **7. Amaç** | Kendi çalışmanızla bağlantı | *The present study aims to address this gap.* |\n\n**Bu ünitedeki araçları birleştirin:**\n\n- **İsimleştirme:** *the use of electronic devices*, *the release of melatonin*\n- **Karmaşık isim öbekleri:** *the relationship between screen time and children's sleep*\n- **Bildirme fiilleri:** *report, argue, acknowledge, found*\n- **Sentez:** *These findings are consistent with ... / However, ... / Moreover, ...*\n- **Temkinli dil** (C1 Ünite 6): *may, is associated with, suggests*\n\n**Sık yapılan hatalar:**\n\n1. Kaynakları **tek tek sıralamak** (*Kaya says ... Chen says ...*)\n2. Sadece **olumlu** bulguları aktarmak\n3. **Boşluğu** belirtmemek\n4. Aşırı **kesin** dil (*proves, always*)",
     "examples": [{"en": "X has received considerable attention in recent years.", "tr": "X son yıllarda büyük ilgi görmüştür."},
                  {"en": "However, the evidence is not entirely consistent.", "tr": "Ancak kanıtlar tamamen tutarlı değildir."},
                  {"en": "Little is known about the long-term effects.", "tr": "Uzun vadeli etkiler hakkında çok az şey bilinmektedir."}],
     "turkishNote": "Türk üniversitelerinde yazılan tezlerde literatür bölümü bazen \"X şunu söylemiştir, Y şunu söylemiştir\" şeklinde kronolojik bir liste olarak yazılır. Uluslararası akademik yazımda ise tematik sentez ve eleştirel değerlendirme beklenir: Kaynaklar hangi noktalarda birleşiyor, hangi noktalarda ayrışıyor, yöntemleri ne kadar güvenilir ve henüz neyi bilmiyoruz? Ayrıca \"literatürde boşluk\" (gap) belirtmek, kendi çalışmanızın neden önemli olduğunu göstermenin en etkili yoludur."},
    [
        mc("İyi bir literatür değerlendirmesi:", ["Kaynakları kronolojik olarak sıralar.", "Kaynakları tematik olarak sentezler ve değerlendirir."], 1, "Sentez."),
        mc("Literatürdeki boşluğu belirten cümle:", ["To date, few studies have examined ...", "Kaya (2019) found that ..."], 0, "Gap."),
        mc("Eleştirel değerlendirme:", ["Most studies rely on self-reports, which may not be accurate.", "All studies agree completely."], 0, "Sınırlılık."),
        mc("Akademik dilde daha uygun:", ["Screens prove that children sleep less.", "Screen use is associated with shorter sleep."], 1, "Temkinli dil."),
        gap("This topic has received considerable ___ in recent years. (ilgi)", ["attention", "interest"], "attention."),
        gap("Little is ___ about the long-term effects of the treatment.", ["known"], "Little is known."),
        gap("The present study ___ to address this gap. (amaçlamak)", ["aims", "seeks", "attempts"], "aims to."),
        gap("However, the evidence is not entirely ___. (tutarlı)", ["consistent", "conclusive"], "consistent."),
        listen("Most research on this topic has been conducted in North America and Western Europe. As a result, little is known about how these findings apply in other cultural contexts. This study, therefore, focuses on families in Turkey and Brazil.", "Bu çalışma hangi boşluğu ele alıyor?", ["Önceki araştırmaların çoğunlukla Kuzey Amerika ve Batı Avrupa'da yapılmış olması", "Önceki araştırmaların çok eski olması", "Önceki araştırmaların sadece çocuklarla yapılmış olması"], 0, "\"conducted in North America and Western Europe ... other cultural contexts\""),
        typ("Boşluğu belirten bir cümle yazın: \"Az sayıda çalışma yaşlı yetişkinleri incelemiştir.\" (To date, ...)", variants("To date, few studies have examined older adults.", "To date, relatively few studies have examined older adults.", "To date, few studies have focused on older adults.", "To date, relatively few studies have focused on older adults.", "To date, few studies have investigated older adults.", "To date, few studies have studied older adults."), "To date, few studies have examined older adults."),
    ],
    {"kind": "writing", "task": write("Aşağıdaki kurgusal kaynakları kullanarak \"The effect of mobile phones in the classroom on learning\" konusunda kısa bir literatür değerlendirmesi yazın (200–250 kelime). Kaynakları sıralamayın, sentezleyin. İsimleştirme, karmaşık isim öbekleri, uygun bildirme fiilleri, temkinli dil ve en az iki sentez kalıbı kullanın; bir sınırlılık ve bir boşluk belirtin.\n\nKaynaklar: Kaya (2020): Telefon yasağından sonra sınav sonuçları %6 arttı; en çok düşük başarılı öğrencilerde. Lewis and Park (2021): Benzer sonuç, ama sadece lise öğrencileri. Mendes (2022): Telefonlar öğretmen rehberliğinde kullanıldığında öğrenmeyi artırabilir. Ortak sınırlılık: Çoğu çalışma kısa süreli (bir dönem). Boşluk: İlkokul öğrencileri ve uzun vadeli etkiler.",
                                      "Mobile phones in the classroom: a brief review\n\nThe presence of mobile phones in classrooms has become an increasingly important issue in educational research. A number of studies have found that restricting phone use may lead to improvements in academic performance (Kaya, 2020; Lewis and Park, 2021). Kaya (2020), for instance, reports a 6% increase in exam results following the introduction of a school-wide ban, with the greatest gains among lower-achieving students. Similarly, Lewis and Park (2021) observed a comparable effect among secondary school students.\n\nHowever, the relationship between phone use and learning appears to be more complex than these findings suggest. Mendes (2022) argues that the key factor is not the device itself but the way in which it is used, noting that teacher-guided activities involving phones were associated with improved learning outcomes. This suggests that a complete ban may not be the only, or necessarily the most effective, solution.\n\nIt should also be noted that most existing studies have been conducted over a single term, which limits the extent to which conclusions can be drawn about long-term effects. Moreover, the majority have focused on secondary schools.\n\nTo date, relatively little is known about the impact of mobile phones on younger learners or about the effects of phone policies over several years. Further research is therefore needed to examine these questions, particularly in primary school contexts.",
                                      ["Tematik sentez (sıralama değil)", "İsimleştirme ve isim öbekleri", "Uygun bildirme fiilleri ve kaynak gösterme", "Temkinli dil", "Sınırlılık ve boşluk"])},
)

u.test([
    mc("İsimleştirilmiş hali: \"Crime fell dramatically.\"", ["There was a dramatic fall in crime.", "Crime had a dramatic falling."], 0, "Nominalisation"),
    mc("Doğru edat: \"an increase ___ prices\"", ["in", "of"], 0, "an increase in"),
    mc("Doğru kalıp:", ["the extent to which", "the extent which"], 0, "the extent to which"),
    mc("Güçlü kanıt için bildirme fiili:", ["suggest", "demonstrate"], 1, "demonstrate"),
    mc("İyi sentez:", ["Kaya says X. Chen says Y.", "While Kaya (2019) found X, Chen (2020) argues Y."], 1, "Sentez"),
    gap("An ___ of the data revealed a surprising trend. (ANALYSE)", ["analysis"], "analysis"),
    gap("The relationship ___ income and health is well documented.", ["between"], "between"),
    gap("The impact of noise ___ concentration was measured.", ["on"], "the impact of X on Y"),
    gap("Morgan ___ al. (2021) reported similar results.", ["et"], "et al."),
    gap("The authors ___ that their sample was small. (kabul etmek)", ["acknowledge", "admit", "concede", "note"], "acknowledge"),
    gap("These findings are ___ with earlier research. (tutarlı)", ["consistent"], "consistent with"),
    gap("To ___, few studies have examined this question. (bugüne kadar)", ["date"], "To date"),
    listen("Although several studies have shown that bilingual children perform better on certain attention tasks, a recent large-scale study by Novak failed to replicate these results. Novak suggests that earlier findings may have been influenced by differences in family income.", "Novak'a göre önceki bulgular neden etkilenmiş olabilir?", ["Örneklemin çok büyük olması", "Ailelerin gelir farklılıkları", "Görevlerin çok kolay olması"], 1, "\"influenced by differences in family income\""),
    typ("İsimleştirin: \"The government introduced the new law, and pollution decreased significantly.\" (The introduction of ...)", variants("The introduction of the new law led to a significant decrease in pollution.", "The introduction of the new law resulted in a significant decrease in pollution.", "The introduction of the new law led to a significant reduction in pollution.", "The introduction of the new law resulted in a significant reduction in pollution.", "The introduction of the new law led to a significant fall in pollution.", "The introduction of the new law caused a significant decrease in pollution."), "The introduction of the new law led to a significant decrease in pollution."),
    write("Aşağıdaki kurgusal kaynakları kullanarak \"The benefits of learning a musical instrument for children\" konusunda kısa bir literatür değerlendirmesi yazın (200–250 kelime). Kaynakları sentezleyin; isimleştirme, karmaşık isim öbekleri, uygun bildirme fiilleri (en az 4 farklı), temkinli dil, en az iki sentez kalıbı, bir sınırlılık ve bir boşluk kullanın.\n\nKaynaklar: Arslan (2019): Müzik eğitimi alan çocukların hafıza testlerinde daha başarılı. Hughes et al. (2021): Benzer sonuç + dil becerilerinde iyileşme. Varga (2022): Etki, aile geliri kontrol edildiğinde büyük ölçüde kayboluyor. Sınırlılık: Çoğu çalışma korelasyonel. Boşluk: Uzun vadeli ve deneysel çalışmalar eksik.",
          "Musical training and children's development: a brief review\n\nThe potential benefits of musical training for children's cognitive development have attracted growing interest in recent years. Several studies have reported a positive association between learning an instrument and memory performance (Arslan, 2019; Hughes et al., 2021). Arslan (2019), for example, found that children who received regular music lessons scored higher on a range of memory tests than their peers. In line with these findings, Hughes et al. (2021) observed similar gains and also noted improvements in children's language skills.\n\nHowever, the extent to which these benefits can be attributed to musical training itself remains unclear. Varga (2022) contends that the effect largely disappears once family income is taken into account, suggesting that the advantages observed in earlier studies may partly reflect differences in children's backgrounds rather than the impact of music. This challenges the assumption that musical training directly causes cognitive improvement.\n\nA further limitation of the existing research is that most studies are correlational, which means that they cannot establish a causal relationship. Hughes et al. (2021) themselves acknowledge this issue.\n\nTo date, relatively few experimental or long-term studies have been carried out. Further research using randomised designs and following children over several years would therefore be valuable in clarifying the relationship between musical training and cognitive development.",
          ["Tematik sentez", "İsimleştirme ve isim öbekleri", "En az 4 farklı bildirme fiili", "Temkinli dil", "Sınırlılık ve boşluk"]),
])

if __name__ == "__main__":
    u.save(sys.argv[1])
